-- V24__expand_bipa_and_myanmar_curriculum.sql
-- Comprehensive expansion of Indonesian (BIPA) and Burmese (Myanmar) curriculum
-- Includes complete 14-day progressive immersion decks with vocabulary, expressions, phonetics, and realistic dialogue examples.

-- 1. Ensure all BIPA-1 decks (1001-1014) exist in course_decks
ON CONFLICT (id) DO UPDATE SET
  title_target = EXCLUDED.title_target,
  title_id = EXCLUDED.title_id,
  title_en = EXCLUDED.title_en,
  title_my = EXCLUDED.title_my;

-- 2. Ensure all Myanmar Foundation decks (2001-2014) exist in course_decks
ON CONFLICT (id) DO UPDATE SET
  title_target = EXCLUDED.title_target,
  title_id = EXCLUDED.title_id,
  title_en = EXCLUDED.title_en,
  title_my = EXCLUDED.title_my;

-- 3. Insert BIPA Course Items for Day 3 through Day 14

-- 4. Insert Myanmar Foundation Course Items for Days 2, 4 through 14

-- 5. Synchronize exact item counts on all course decks
UPDATE course_decks cd
SET item_count = (
  SELECT COUNT(*)
  FROM course_items ci
  WHERE ci.deck_id = cd.id
);
